import { useFormContext } from 'react-hook-form';
import { FormField, FormItem, FormLabel, FormControl, FormMessage } from '@/components/ui/form';
import { Popover, PopoverContent, PopoverTrigger } from '../ui/popover';
import { Button } from '../ui/button';
import { format } from 'date-fns';
import CalendarIcon from '../icons/CalendarIcon';
import { Calendar } from '../ui/calendar';
import { cn } from '@/lib/utils';

function isValidDate(d: unknown): d is Date {
    return d instanceof Date && !Number.isNaN(d.getTime());
}

interface Props {
    className?: string;
    name: string;
    label?: string;
    placeholder?: string;
    disabled?: (date: Date) => boolean;
    /** Extra classes for the popover panel (e.g. when inside a high z-index dialog). */
    popoverContentClassName?: string;
}

export default function DayPickerInputForm({
    className,
    name,
    label,
    placeholder,
    disabled = undefined,
    popoverContentClassName,
}: Props) {
    const { control } = useFormContext();
    return (
        <FormField
            control={control}
            name={name}
            render={({ field }) => {
                const selected = isValidDate(field.value) ? field.value : undefined;
                return (
                    <FormItem className={cn('flex flex-col', className)}>
                        <FormLabel className="text-primery-blue-900 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                            {label}
                        </FormLabel>
                        <Popover>
                            <PopoverTrigger asChild>
                                <FormControl>
                                    <Button
                                        type="button"
                                        variant="outline"
                                        className="pe-3 text-start font-medium flex flex-row justify-between min-h-10 w-full"
                                    >
                                        {selected ? (
                                            format(selected, 'yyyy-MM-dd')
                                        ) : (
                                            <span className="text-white-blue-600">{placeholder}</span>
                                        )}
                                        <CalendarIcon width="24" height="24" className="text-white-blue-600 shrink-0" />
                                    </Button>
                                </FormControl>
                            </PopoverTrigger>
                            <PopoverContent className={cn('w-auto p-0', popoverContentClassName)} align="start">
                                <Calendar
                                    mode="single"
                                    selected={selected}
                                    onSelect={(d) => field.onChange(d)}
                                    disabled={disabled}
                                    initialFocus
                                />
                            </PopoverContent>
                        </Popover>
                        <FormMessage />
                    </FormItem>
                );
            }}
        />
    );
}
